import {mountFeedback} from './feedback-ui.mjs?v=3';
import { mountTeamAdmin } from './admin-teams.mjs';
import { operationsHtml } from './admin-operations.mjs';
import {progressHtml} from './aftercare-ui.mjs?v=2';
import {show} from './main.js?v=14';
import { mountEvidence } from './evidence-ui.mjs';
import { api, requestBody, escapeHtml as esc, showError } from './business-api.mjs';
const root = document.querySelector('#admin-workspace');
const durationText = seconds => seconds == null ? '暂无样本' : seconds < 60 ? seconds+'秒' : Math.round(seconds/60)+'分钟';
function metricsHtml(m) {
  return '<section class="workspace-panel"><h2>售后处理概览</h2><p>共'+m.total+'件 · 待处理'+m.open+'件 · 已记录人工操作'+m.humanActions+'次</p><p>平均首次响应：'+durationText(m.averageResponseSeconds)+'（'+m.responseSamples+'件） · 平均结案历时：'+durationText(m.averageResolutionSeconds)+'（'+m.closedSamples+'件）</p><p class="evidence-note">历时包含等待双方回应，不等于人工实际工作时间。新记录'+m.tracked+'件；旧记录'+m.legacy+'件缺少完整时间，不纳入耗时均值。</p><div class="aftercare-reasons">'+m.byKind.map(k=>'<p>'+esc(k.label)+'：'+k.total+'件 / 待处理'+k.open+'件</p>').join('')+'</div></section>';
}
async function render() {
  try {
    const data = await api('/api/admin');
    root.innerHTML = `<div class="workspace-top"><div><p class="workspace-kicker">本机业务管理</p><h1>平台处理台</h1></div><a class="workspace-button" href="./account.html">返回用户中心</a></div><p>处理需要明确理由，操作会留痕。支付和退款均为模拟，无真实资金。AI与社区评审未接入。</p>${operationsHtml(data.operations)}${metricsHtml(data.aftercareMetrics)}<h2>需关注的订单</h2>${data.attention.map(o=>`<section class="workspace-panel"><strong>${esc(o.flag.label)}</strong><p>${esc(o.id)}</p><button class="text-link" data-inspect="${o.id}">查看服务记录</button><p>仅提醒，未自动认责、退款或结束订单。</p></section>`).join('') || '<p>暂无达到提醒条件的订单。</p>'}<h2>待处理售后</h2>${data.cases.map(o => `<section class="workspace-panel"><h3>${esc(o.snapshot.title)} · ${esc(o.id)}</h3>${progressHtml(o.case,"admin")}<p>${esc(o.case.description)}</p>${o.case.proposal ? `<p>当前方案：${esc(({refund:"按规则退款",resume:"恢复流程",replace:"更换服务者",adjustTime:"校正时长"})[o.case.proposal.outcome])} · ${esc(o.case.proposal.reason)}</p>` : ""}<p>材料摘要：${esc(o.case.evidence.join('；') || '暂无')}</p>${o.case.notes.map(n => `<p>${esc(({buyer:"消费者",provider:"服务者"})[n.role] || "参与者")}：${esc(n.text)}</p>`).join('')}<div data-case-attachments data-order="${o.id}" data-case="${o.case.id}"></div><form class="order-form case-form" data-id="${o.id}" data-version="${o.version}"><label>处理方案<select name="outcome"><option value="requestMaterials">请求补充材料（不决定责任）</option><option value="resume">不适用退款，恢复原流程</option><option value="refund">按规则退款（${o.case.percent}%）</option><option value="replace">更换服务者，保留剩余时长</option><option value="adjustTime">校正时长（仅时长异议）</option></select></label><label>补证对象（请求材料时适用）<select name="forRole"><option value="buyer">消费者</option><option value="provider">服务者</option></select></label><label>校时分钟（增加已服务时间为正，补还时间为负）<input name="deltaMinutes" type="number" min="-60" max="60" step="1" value="0"></label><label>核实依据与原因<textarea name="reason" minlength="10" maxlength="300" required></textarea></label>${o.case.stage === 'appeal' ? '<label><input type="checkbox" name="final">已人工复核，执行最终结果</label>' : ''}<button class="workspace-button" ${o.case.stage === 'proposed' ? 'disabled' : ''}>${o.case.stage === 'proposed' ? '等待双方确认或异议' : '提交处理方案'}</button></form></section>`).join('') || '<p>暂无待处理售后。</p>'}<h2>服务者接单状态</h2>${data.profiles.map(p => `<section class="workspace-panel"><form class="order-form suspension-form" data-id="${esc(p.userId)}" data-suspended="${p.suspended}"><h3>${esc(p.gameId)} · ${esc(({available:"可接单",idle:"未开启接单",serving:"服务中",suspended:"暂停新接单"})[p.state])}</h3><p>${esc(p.reason)}</p><label>核实依据与恢复说明<textarea name="reason" minlength="10" maxlength="300" required></textarea></label><button class="workspace-button">${p.suspended ? '恢复接单' : '暂停新接单'}</button></form></section>`).join('')}<h2>商品管理</h2>${data.products.map(p => `<section class="workspace-panel"><form class="order-form product-form" data-id="${p.id}"><h3>${esc(p.title)}</h3><label>价格（元）<input type="number" name="price" min="0.01" max="1000" step="0.01" value="${(p.price / 100).toFixed(2)}" required></label><label>服务状态<select name="status"><option value="available" ${p.status === 'available' ? 'selected' : ''}>上架</option><option value="offline" ${p.status === 'offline' ? 'selected' : ''}>下架</option></select></label><label>修改原因<textarea name="reason" minlength="10" maxlength="300" required></textarea></label><button class="workspace-button">保存商品</button></form></section>`).join('')}<h2>最近操作记录</h2><ol class="service-timeline">${data.audit.map(a => `<li>${esc(a.action)}：${esc(a.reason)}<small>${esc(a.target_id)}</small></li>`).join('')}</ol><p id="admin-error" role="status"></p>`;
    root.querySelectorAll('[data-inspect]').forEach(button=>button.onclick=async()=>{ try { const {order}=await api('/api/orders/'+button.dataset.inspect); show('订单服务记录', '<p>'+esc(order.id)+'</p><ol class="service-timeline">'+order.events.map(e=>'<li>'+esc(e.label)+'<small>'+esc(e.time)+'</small></li>').join('')+'</ol>',button); } catch(error){showError(error,document.querySelector('#admin-error'));} });
    root.querySelectorAll('[data-case-attachments]').forEach(node => mountEvidence(node, { orderId: node.dataset.order, caseId: node.dataset.case }));
    root.querySelectorAll('.case-form').forEach(form=>{const update=()=>{const material=form.elements.outcome.value==='requestMaterials'; form.elements.forRole.closest('label').hidden=!material; form.elements.deltaMinutes.closest('label').hidden=form.elements.outcome.value!=='adjustTime'; if(form.elements.final) form.elements.final.closest('label').hidden=material; const button=form.querySelector('button'); if(!button.disabled) button.textContent=material?'提交补证要求':'提交处理方案';}; form.elements.outcome.onchange=update;update();});
    root.querySelectorAll('form').forEach(form => form.onsubmit = async event => {
      event.preventDefault(); const b = form.querySelector('button'); b.disabled = true;
      try {
        if (form.classList.contains('retry-form')) await api('/api/admin/retry', requestBody({ id: form.dataset.id, kind: form.dataset.kind, reason: form.elements.reason.value }));
        else if (form.classList.contains('case-form')) await api(`/api/orders/${form.dataset.id}/actions/${form.elements.outcome.value === "requestMaterials" ? "requestMaterials" : "proposeCase"}`, requestBody({ forRole:form.elements.forRole.value, version: Number(form.dataset.version), outcome: form.elements.outcome.value, deltaSeconds: Number(form.elements.deltaMinutes.value)*60, reason: form.elements.reason.value, final: !!form.elements.final?.checked }));
        else if (form.classList.contains('suspension-form')) await api('/api/admin/suspend', requestBody({ userId: form.dataset.id, suspended: form.dataset.suspended !== 'true', reason: form.elements.reason.value }));
        else await api('/api/admin/product', requestBody({ id: form.dataset.id, price: Math.round(Number(form.elements.price.value) * 100), status: form.elements.status.value, reason: form.elements.reason.value }));
        await render();
      } catch (error) { showError(error, document.querySelector('#admin-error')); b.disabled = false; }
    });
    await mountTeamAdmin(root);
    mountFeedback();
  } catch (error) { root.textContent = error.message; showError(error); }
}
render();


